# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import torch
import triton
import triton.language as tl


@triton.jit
def _gt_scalar_kernel(a_ptr, N, scalar, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    nprog = tl.num_programs(0)
    stride = nprog * BLOCK
    base = pid * BLOCK
    for off in range(base, N, stride):
        offs = off + tl.arange(0, BLOCK)
        mask = offs < N
        a = tl.load(a_ptr + offs, mask=mask)
        res = a > scalar
        tl.store(a_ptr + offs, res.to(a_ptr.dtype.element_ty), mask=mask)


# Ascend coreDim (grid dim 0) must be <= 65535.
_MAX_GRID = 65535
_NUM_VCORE = None


def _num_vectorcore():
    global _NUM_VCORE
    if _NUM_VCORE is None:
        try:
            from triton.backends.compiler import GPUTarget  # noqa: F401
        except Exception:
            pass
        try:
            import triton.runtime.driver as _drv

            props = _drv.driver.active.utils.get_device_properties(
                torch.npu.current_device()
            )
            _NUM_VCORE = int(props.get("num_vectorcore", 0)) or 0
        except Exception:
            _NUM_VCORE = 0
    return _NUM_VCORE


def gt_scalar_(A, B):
    # In-place greater-than-scalar: A = A.gt_(B); returns A (aliased).
    if isinstance(B, torch.Tensor):
        b = B.item()
    else:
        b = B

    N = A.numel()
    if N == 0:
        return A

    a_flat = A.view(-1) if A.is_contiguous() else A.contiguous().view(-1)

    BLOCK = 8192
    nblocks = triton.cdiv(N, BLOCK)

    # Cap grid at a few waves over the physical vector cores so medium shapes
    # grid-stride contiguous work instead of launching thousands of tiny tiles.
    nvcore = _num_vectorcore()
    if nvcore > 0:
        grid_cap = min(_MAX_GRID, nvcore * 32)
    else:
        grid_cap = _MAX_GRID
    grid = (min(nblocks, grid_cap),)
    _gt_scalar_kernel[grid](a_flat, N, b, BLOCK=BLOCK)

    # If A was non-contiguous we computed into a contiguous copy; write back.
    if not A.is_contiguous():
        A.copy_(a_flat.view_as(A))

    return A
